import { Vector3 } from '../math/index.js';
/** Keeps local renderer coordinates precise while preserving an accumulated world origin. */
export class WorldOriginRebaser {
    accumulatedOrigin = new Vector3();
    threshold;
    gridSize;
    shifts = 0;
    constructor(options = {}) {
        this.threshold = Math.max(1, options.threshold ?? 10_000);
        this.gridSize = Math.max(1, options.gridSize ?? 1_000);
    }
    update(reference, roots) {
        if (reference.length() < this.threshold)
            return this.result(false, 0, 0, 0);
        const x = Math.round(reference.x / this.gridSize) * this.gridSize;
        const y = Math.round(reference.y / this.gridSize) * this.gridSize;
        const z = Math.round(reference.z / this.gridSize) * this.gridSize;
        if (x === 0 && y === 0 && z === 0)
            return this.result(false, 0, 0, 0);
        for (const root of roots)
            root.position.set(root.position.x - x, root.position.y - y, root.position.z - z);
        this.accumulatedOrigin.add(new Vector3(x, y, z));
        this.shifts += 1;
        return this.result(true, x, y, z);
    }
    toGlobal(local, target = new Vector3()) { return target.copy(local).add(this.accumulatedOrigin); }
    toLocal(global, target = new Vector3()) { return target.copy(global).sub(this.accumulatedOrigin); }
    reset() { this.accumulatedOrigin.set(0, 0, 0); this.shifts = 0; }
    result(shifted, x, y, z) {
        return Object.freeze({ shifted, offset: [x, y, z], accumulatedOrigin: this.accumulatedOrigin.toArray() });
    }
}